WITH ValidOrderItems AS (SELECT *, CAST(unit_price AS INT) AS unit_price_int FROM order_items WHERE NOT (quantity = 4 OR quantity < 5)), Agg AS (SELECT CASE WHEN unit_price >= 320 THEN 'high' WHEN unit_price >= 170 THEN 'mid' ELSE 'low' END AS unit_price_bucket, MAX(unit_price_int) - MIN(unit_price_int) AS unit_price_int_range FROM ValidOrderItems GROUP BY CASE WHEN unit_price >= 320 THEN 'high' WHEN unit_price >= 170 THEN 'mid' ELSE 'low' END) SELECT unit_price_bucket, unit_price_int_range FROM Agg ORDER BY unit_price_int_range DESC
